        "titolo_orig": "Hanoi cambia volto",
        "testo_it": "La capitale vietnamita Hanoi affronta un'ondata di caldo estremo con temperature record già a fine maggio.",
        "priorita": "Bassa",
        "id_gruppo": 22,
        "link": "https://www.internazionale.it/notizie/junko-terao/2026/06/02/hanoi-cambia-volto",
